# Ensure both event_start_time and now are datetime.datetime objects (not date)
if type(event_start_time) == "date":
    event_start_time_dt = datetime.combine(event_start_time, datetime.strptime("00:00", "%H:%M").time())
else:
    event_start_time_dt = event_start_time

if type(now) == "date":
    now_dt = datetime.combine(now, datetime.strptime("00:00", "%H:%M").time())
else:
    now_dt = now

time_diff = event_start_time_dt - now_dt
total_seconds = int(time_diff.total_seconds())
if total_seconds < 0:
    print("The lunch with Sarah has already started or passed.")
else:
    hours = total_seconds // 3600
    minutes = (total_seconds % 3600) // 60
    print("{:02d}:{:02d}".format(hours, minutes))
